function isPlainObject(value: any): value is Record<string, any> {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function hasOwn(obj: Record<string, any>, key: string): boolean {
  return Object.prototype.hasOwnProperty.call(obj, key);
}

function canonicalStringify(value: any): string {
  if (Array.isArray(value)) {
    return '[' + value.map(canonicalStringify).join(',') + ']';
  }
  if (isPlainObject(value)) {
    const keys = Object.keys(value).sort();
    return '{' + keys.map((key) => JSON.stringify(key) + ':' + canonicalStringify(value[key])).join(',') + '}';
  }
  return JSON.stringify(value) as string;
}

function deepMerge(a: any, b: any): any {
  if (isPlainObject(a) && isPlainObject(b)) {
    const result: Record<string, any> = {};
    const keys = new Set<string>([...Object.keys(a), ...Object.keys(b)]);

    for (const key of keys) {
      const inA = hasOwn(a, key);
      const inB = hasOwn(b, key);

      if (inA && inB) {
        result[key] = deepMerge(a[key], b[key]);
      } else if (inA) {
        result[key] = a[key];
      } else {
        result[key] = b[key];
      }
    }

    return result;
  }

  if (Array.isArray(a) && Array.isArray(b)) {
    const combined = [...a, ...b];
    const seen = new Set<string>();
    const result: any[] = [];

    for (const item of combined) {
      const key = canonicalStringify(item);
      if (!seen.has(key)) {
        seen.add(key);
        result.push(item);
      }
    }

    return result;
  }

  return b;
}

function sortDeep(value: any): any {
  if (Array.isArray(value)) {
    return value.map(sortDeep);
  }

  if (isPlainObject(value)) {
    const result: Record<string, any> = {};
    const keys = Object.keys(value).sort();

    for (const key of keys) {
      result[key] = sortDeep(value[key]);
    }

    return result;
  }

  return value;
}

