    char tmp[32];
    int neg = 0;
    if (value < 0) { neg = 1; value = -value; }
    snprintf(tmp, sizeof(tmp), "%lld", value);
    int len = (int)strlen(tmp);
    int commas = (len - 1) / 3;
    int outlen = len + commas + neg;
    int i = outlen - 1;
    int j = len - 1;
    int cnt = 0;
    while (j >= 0) {
        out[i--] = tmp[j--];
        cnt++;
        if (cnt == 3 && j >= 0) {
            out[i--] = ',';
            cnt = 0;
        }
    }
    if (neg) out[0] = '-';
    out[outlen] = '\0';
}

