void init_count_list(CountList *l) {
    l->items = NULL;
    l->len = 0;
    l->cap = 0;
}

void init_string_list(StringList *l) {
    l->items = NULL;
    l->len = 0;
    l->cap = 0;
}

int find_or_add_count(CountList *l, const char *name, size_t len) {
    for (size_t i = 0; i < l->len; i++) {
        if (strlen(l->items[i].name) == len &&
            strncmp(l->items[i].name, name, len) == 0) {
            return (int)i;
        }
    }

    if (l->len == l->cap) {
        size_t newcap = l->cap ? l->cap * 2 : 8;
        CountItem *ni = realloc(l->items, newcap * sizeof(CountItem));
        if (!ni) return -1;
        l->items = ni;
        l->cap = newcap;
    }

    char *copy = malloc(len + 1);
    if (!copy) return -1;
    memcpy(copy, name, len);
    copy[len] = '\0';

    l->items[l->len].name = copy;
    l->items[l->len].count = 0;
    return (int)l->len++;
}

int add_unique_string(StringList *l, const char *s) {
    for (size_t i = 0; i < l->len; i++) {
        if (strcmp(l->items[i], s) == 0) return 0;
    }

    if (l->len == l->cap) {
        size_t newcap = l->cap ? l->cap * 2 : 8;
        char **ni = realloc(l->items, newcap * sizeof(char *));
        if (!ni) return 0;
        l->items = ni;
        l->cap = newcap;
    }

    size_t n = strlen(s);
    char *copy = malloc(n + 1);
    if (!copy) return 0;
    memcpy(copy, s, n + 1);

    l->items[l->len++] = copy;
    return 1;
}

