static char *read_file(const char *path) {
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = malloc((size_t)sz + 1);
    if (!buf) { fclose(f); return NULL; }
    size_t rd = fread(buf, 1, (size_t)sz, f);
    buf[rd] = 0;
    fclose(f);
    return buf;
}

static const char *skip_ws(const char *p) {
    while (*p && (*p==' '||*p=='\t'||*p=='\n'||*p=='\r')) p++;
    return p;
}

static const char *parse_string(const char *p, char **out) {
    p = skip_ws(p);
    if (*p != '"') return NULL;
    p++;
    const char *q = p;
    size_t len = 0;
    while (*q && *q != '"') {
        if (*q == '\\') { q++; if (*q) q++; len++; }
        else { q++; len++; }
    }
    if (*q != '"') return NULL;
    char *s = malloc(len + 1);
    if (!s) return NULL;
    size_t j = 0;
    while (*p && *p != '"') {
        if (*p == '\\') {
            p++;
            if (*p == 'n') s[j++] = '\n';
            else if (*p == 't') s[j++] = '\t';
            else if (*p == 'r') s[j++] = '\r';
            else if (*p == 'b') s[j++] = '\b';
            else if (*p == 'f') s[j++] = '\f';
            else if (*p == '/') s[j++] = '/';
            else if (*p == '"') s[j++] = '"';
            else if (*p == '\\') s[j++] = '\\';
            else s[j++] = *p;
            if (*p) p++;
        } else {
            s[j++] = *p++;
        }
    }
    s[j] = 0;
    *out = s;
    return p + 1;
}

