func walk(_ dirPath: String, _ relativeDir: String) {
    guard let entries = try? fm.contentsOfDirectory(atPath: dirPath) else { return }
    for entry in entries {
        let fullPath = dirPath + "/" + entry
        let relPath = relativeDir.isEmpty ? entry : relativeDir + "/" + entry
        var st = stat()
        let result = fullPath.withCString { lstat($0, &st) }
        if result != 0 {
            continue
