        let mode = st.st_mode & 0o170000
        if mode == 0o120000 {
            continue
        } else if mode == 0o040000 {
            walk(fullPath, relPath)
        } else if mode == 0o100000 {
            processFile(fullPath, relPath)
        }
    }
}

