func multiply(_ A: [[Int]], _ B: [[Int]]) -> [[Int]] {
    let rowsA = A.count
    let colsA = A[0].count
    let colsB = B[0].count
    var C = Array(repeating: Array(repeating: 0, count: colsB), count: rowsA)

    for i in 0..<rowsA {
        for j in 0..<colsB {
            var sum = 0
            for k in 0..<colsA {
                sum += A[i][k] * B[k][j]
            }
            C[i][j] = sum
        }
    }

    return C
}

func determinant3(_ M: [[Int]]) -> Int {
    let a = M[0][0], b = M[0][1], c = M[0][2]
    let d = M[1][0], e = M[1][1], f = M[1][2]
    let g = M[2][0], h = M[2][1], i = M[2][2]

    return a * (e * i - f * h) - b * (d * i - f * g) + c * (d * h - e * g)
}

func field(_ value: Int) -> String {
    let text = String(value)
    let padding = max(0, 4 - text.count)
    return String(repeating: " ", count: padding) + text
}

func printMatrix(_ M: [[Int]]) {
    for row in M {
        let line = row.map { field($0) }.joined(separator: " ")
        print("  " + line)
    }
}

