fn print_matrix(m: &[[i32; 3]; 3]) {
    for row in m.iter() {
        print!("  ");
        for (j, &v) in row.iter().enumerate() {
            if j > 0 {
                print!(" ");
            }
            print!("{:4}", v);
        }
        println!();
    }
}

fn determinant(m: &[[i32; 3]; 3]) -> i32 {
    m[0][0] * (m[1][1] * m[2][2] - m[1][2] * m[2][1])
        - m[0][1] * (m[1][0] * m[2][2] - m[1][2] * m[2][0])
        + m[0][2] * (m[1][0] * m[2][1] - m[1][1] * m[2][0])
}
